def test_infinite_numeric_bounds_are_rejected_at_repository_level() -> None:
    # Non-finite floats cannot be expressed in strict JSON, so the finite check
    # is exercised directly against the repository.
    for value in (math.inf, -math.inf, math.nan):
        try:
            with db_session() as conn:
                repository.create_quality_rule(
                    conn,
                    "orders",
                    1,
                    f"r-{value}",
                    "numeric_range",
                    {"field": "amount", "min": value, "max": 10},
                )
        except Exception as exc:  # noqa: BLE001
            assert exc.__class__.__name__ == "RequestInvalidError"
        else:  # pragma: no cover
            raise AssertionError("non-finite bound was accepted")

    # Rollback of the failed attempts means no rows survive; seed fresh data and
    # confirm a valid rule can still be created afterwards.
    from fastapi.testclient import TestClient

    from app.main import app

    with TestClient(app) as client:
        make_dataset_with_version(client, "orders2")
        response = client.post(
            f"/datasets/orders2/versions/1/quality-rules",
            json={
                "name": "ok",
                "kind": "numeric_range",
                "params": {"field": "amount", "min": 0, "max": 10},
            },
        )
        assert response.status_code == 201


